// W3C traceparent: version-traceid-parentspanid-flags
const incoming = "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01";

function parse(h) {
  const p = h.split("-");
  const ok = p.length === 4 && /^[0-9a-f]{32}$/.test(p[1]) && /^[0-9a-f]{16}$/.test(p[2]);
  if (!ok || /^0+$/.test(p[1])) return null;       // all-zero trace id is invalid
  return { version: p[0], traceId: p[1], parentId: p[2], sampled: (parseInt(p[3], 16) & 1) === 1 };
}

// A new hop keeps the trace id, makes a new span id, and passes the flags on
function nextHeader(ctx, newSpanId) {
  return [ctx.version, ctx.traceId, newSpanId, ctx.sampled ? "01" : "00"].join("-");
}

console.log("incoming :", incoming);
const ctx = parse(incoming);
console.log("parsed   :", JSON.stringify(ctx));
console.log("outgoing :", nextHeader(ctx, "b7ad6b7169203331"));
